/// <summary>
/// MPJ_21275_BackOrders
/// Extension of SalesTable form datasource of SalesTable
/// </summary>
[ExtensionOf(formDataSourceStr(SalesTable, SalesTable))]
final class METSalesTable_SalesTable_Extension
{
}

Method.Source:
    /// <summary>
    /// MPJ_21275_BackOrders
    /// Based up on the Customer master Allow back orders check box Sales header allow back order check box will be activated
    /// </summary>
    public void init()
    {
        SalesTable          salesTable          =  this.formRun().args().record();
        SalesTable          salesTableBackOrder = SalesTable::findRecId(salesTable.RecId, true);
        METCustTable        metCustTable;
        FormCheckBoxControl metAllowBackOrders  = this.formRun().design().controlName(formControlStr(SalesTable, METAllowBackOrders)) as FormCheckBoxControl;

        metCustTable = METCustTable::find(salesTable.CustAccount);

        next init();

        ttsbegin;
        if (metCustTable.AllowBackOrders == NoYes::Yes )
        {
            salesTableBackOrder.METAllowBackOrders = NoYes::Yes;
            salesTableBackOrder.update();
            metAllowBackOrders.allowEdit(true);
        }
        else if (metCustTable.AllowBackOrders == NoYes::No)
        {
            salesTableBackOrder.METAllowBackOrders = NoYes::No;
            salesTableBackOrder.update();
            metAllowBackOrders.allowEdit(false);
        }
        ttscommit;

        salesTable.reread();
    }
